from copy import deepcopy
import re
from lxml import objectify
from taf.internal.scf.exceptions import ElementNotFound
from taf.internal.scf.list import List
from taf.internal.scf.element import Element
from taf.internal.scf.p import P
from taf.internal.scf.tree_object import TreeListObject


class ManagedObject(TreeListObject):
    def __init__(self, tree=None):
        super(ManagedObject, self).__init__(tree)

    @property
    def dist_name(self):
        return self._tree.attrib['distName']

    def __getattr__(self, item):
        """
        Method looks for and returns in order:
        1) Managed Object child of Managed Object type with passed name. If not
        2) Sorted list of Managed Objects children of Managed Object type.
            The MOs on the list are the MOs with the name starting with passed name,
            dash and the number identifier.They are ordered by the number identifier. If not
        3) Child element of Managed Object of P or List type.

        :param str item: Name of item to return
        :raises: ElementNotFound: Raises if there in no child element of any type with given name.
        :return: requested element or elements
        """
        if item.startswith("__"):
            return super(ManagedObject, self).__getattr__(item)

        item_escaped = re.sub(r"_(?=\d+$)", "-", item)
        try:
            ns = self._tree.nsmap[None]
        except KeyError:
            ns = None

        dist_name = self.dist_name + '/' + item_escaped
        mo_result = self.find_single_mo(dist_name, self._tree.getparent(), ns)

        if mo_result is not None:
            return ManagedObject(mo_result)

        mos = [ManagedObject(mo) for mo in self.find_multiple_mos(dist_name, self._tree.getparent(), ns)]
        mos.sort()
        if len(mos) > 0:
            return mos

        try:
            classes = [('list', List), ('element', Element), ('p', P)]
            element = self.find_element(item, self._tree)
            return self.return_scf_element(element=element, classes=classes)
        except IndexError:
            raise ElementNotFound("Element {item} not found.".format(item=item))

    class ManagedObjectIterator:
        def __init__(self, tree, mo):
            self._mo = mo
            self._tree = tree
            self._current_index = 0

        def __next__(self):
            index = self._current_index
            classes = [('list', List), ('p', P)]
            try:
                child = self._tree.getchildren()[index]
                result = TreeListObject.return_scf_element(element=child, classes=classes)
                self._current_index += 1
                return result
            except IndexError:
                self._current_index = 0
                raise StopIteration

        def next(self):
            return self.__next__()

        def __iter__(self):
            return self

    def __iter__(self):
        return ManagedObject.ManagedObjectIterator(self._tree, self)

    def __gt__(self, second):
        match_numb = "[0-9]+$"
        first_numb = int(re.search(match_numb, self.dist_name).group(0))
        second_numb = int(re.search(match_numb, second.dist_name).group(0))
        return first_numb > second_numb

    def get_all_descendant_mos(self):
        return [ManagedObject(mo) for mo in self._find_flat_children(self._tree.nsmap[None], self.dist_name)]

    def clone_tree_to(self, target_path):
        old_distname = self.dist_name
        ns = self._tree.nsmap[None]
        for mo in self._find_flat_children(ns, dist_name=self.dist_name):
            mo_tree = deepcopy(mo)
            mo_tree.attrib['distName'] = re.sub("^" + old_distname, target_path, mo_tree.attrib['distName'])
            self._tree.getparent().append(mo_tree)
        cloned_tree = deepcopy(self._tree)
        cloned_tree.attrib['distName'] = target_path
        self._tree.getparent().append(cloned_tree)

    def clone_to(self, target_path):
        cloned_tree = deepcopy(self._tree)
        cloned_tree.attrib['distName'] = target_path
        self._tree.getparent().append(cloned_tree)

    def remove(self):
        self._tree.getparent().remove(self._tree)

    def remove_tree(self):
        ns = self._tree.nsmap[None]
        for mo in self._find_flat_children(ns, dist_name=self.dist_name):
            self._tree.getparent().remove(mo)
        self._tree.getparent().remove(self._tree)

    def append(self, element):
        self._tree.append(element._tree)

    def create(self, klass, dist_name=None, version=None, operation=None, id=None, name=None, vendor=None,
               time_stamp=None, ns='raml21.xsd'):
        element = objectify.ObjectifiedElement()
        element.tag = '{' + ns + '}managedObject'
        element.attrib['class'] = klass

        attributes = {
            'distName': dist_name,
            'version': version,
            'operation': operation,
            'id': id,
            'name': name,
            'vendor': vendor,
            'timeStamp': time_stamp
        }

        for key, value in attributes.items():
            if value is not None:
                element.attrib[key] = value

        self._tree = element
        return self
